import React from "react";

import MediaPicker from "../quick-form/media-picker";
import QuickForm, { QuickFormSchemaMetaType } from "../quick-form/quick-form";

import { EventPerformance, timeData } from '../../models/models';

import ValidationService, { COMMON_REGEXES, Schema } from "../../services/validation.service";
import EventService from "../../services/event.service";

const { periods, weekdays, months, daysPerMonth, years, dates, times } = timeData;

type Props = {
  mediaList: string[],
  resolve: (eventPerformance: EventPerformance | null) => any
  init?: EventPerformance,
};

type FormEvent = Omit<EventPerformance, "month" | "day" | "year" | "time" | "period"> & { 
  month: "Month" | EventPerformance["month"],
  day: "Day" | EventPerformance["day"],
  year: "Year" | EventPerformance["year"],
  time: "Time" | EventPerformance["time"],
  period: "Period" | EventPerformance["period"]
}

const eventFormSchema: Schema<QuickFormSchemaMetaType> = {
  day: { 
    type: Array(32).fill(0).map((v,i) => (i+1).toString()), attributes: { required: true, range: { min: 1, max: 32 } },
    meta: { quickForm: { inputClassName: "h-2 pl-3 pr-0 text-sm leading-8 min-h-8 rounded-lg invalid:text-gray-500", hideErrorMessages: true }}
  },
  month: { 
    type: [...months], attributes: { required: true },
    meta: { quickForm: { inputClassName: " h-2 pl-3 pr-0 text-sm leading-8 min-h-8 rounded-lg" }}
  },
  year: { 
    type: Array(100).fill(0).map((v,i) => (i+2020).toString()), attributes: { required: true, range: { min: 2020, max: 2120 } },
    meta: { quickForm: { inputClassName: " h-2 pl-3 pr-0 text-sm leading-8 min-h-8 rounded-lg" }}
  },
  time: { 
    type: [...times], attributes: { required: true },
    meta: { quickForm: { inputClassName: " h-2 pl-3 pr-0 text-sm leading-8 min-h-8 rounded-lg" }}
  },
  location: { 
    type: COMMON_REGEXES.COMMON_WRITING, attributes: { required: true, strLength: { minLength: 1, maxLength: 32 } },
    meta: { quickForm: { placeholder: 'Venue' }}
  },
  addressa: { 
    type: COMMON_REGEXES.COMMON_WRITING, attributes: { required: false },
    meta: { quickForm: { placeholder: 'Address Line 1' }}
  },
  addressb: { 
    type: COMMON_REGEXES.COMMON_WRITING, attributes: { required: false },
    meta: { quickForm: { placeholder: 'Address Line 2' }}
  },
  thumbnail: { 
    type: 'string', 
    attributes: { required: false },
    meta: {
      quickForm: {
        CustomInput: MediaPicker,
        customInputProps: { }
      }
    }
  },
  description: { 
    type: 'string', //COMMON_REGEXES.COMMON_WRITING, 
    attributes: { required: true, strLength: { minLength: 5 } },
    meta: {
      quickForm: {
        textArea: true, textAreaRows: 4,
        placeholder: 'Write your event description here...'
      }
    }
  },
  website: { type: 'string', attributes: { required: false }, meta: { quickForm: { placeholder: 'Website' }}},
  media: { type: 'string', attributes: { required: false, array: { minLength: 0 }}},
  period: { type: [...periods], attributes: { required: true } }
};

const thumbnailPartitionedSchema = (({ thumbnail }) => ({ thumbnail }))(eventFormSchema);
const monthPartitionedSchema = (({ month }) => ({ month }))(eventFormSchema);
const dayPartitionedSchema = (({ day }) => ({ day }))(eventFormSchema);
const yearPartitionedSchema = (({ year }) => ({ year }))(eventFormSchema);
const timePartitionedSchema = (({ time }) => ({ time }))(eventFormSchema);
const remainingPartitionSchema = (({ period, location, website, addressa, addressb, description }) => ({ period, location, website, addressa, addressb, description }))(eventFormSchema);

const VerticalEventForm: React.FC<Props> = ({ mediaList, resolve, init }) => {

  const [model, setModel] = React.useState<FormEvent>({
    id: init?.id || -1, timestamp: init?.timestamp || -1,
    day: init?.day || "Day", month: init?.month ||'Month', year: init?.year || "Year", 
    time: init?.time ||"Time", website: init?.website || '', location: init?.location ||'', 
    addressa: init?.addressa || "", addressb: init?.addressb || "",
    thumbnail: init?.thumbnail || '', description: init?.description || '', period: init?.period || 'Period', media: init?.media || []
  });
  const [periodPhrase, setPeriodPhrase] = React.useState<string>('')
  const [touched, setTouched] = React.useState<boolean>(false);
  const [formErrors, setFormErrors] = React.useState<{ key: string, message: string }[]>([]);
  const [showImgMenu, setShowImgMenu] = React.useState<boolean>(false);

  // React.useEffect(() => {

  //   (async () => {
      

  //   })();
  //   console.log('init', model);
  // }, []);

  React.useEffect(() => {
    ( async () => setPeriodPhrase((await EventService.periodPrases(model)).body || '') )();
    // console.log('updated', model);
  }, [model]);

  return (
    <div className="bg-white text-center max-h-screen overflow-y-scroll">

      <div className="p-1 border border-gray-300 rounded shadow-md w-96 text-left mx-auto">
        <div className="m-4 ">
          <div className="">
            <QuickForm<Pick<FormEvent, "thumbnail">> 
              schema={thumbnailPartitionedSchema}
              init={{thumbnail: model.thumbnail || ''}}
              onInput={(err, tm) => {
                setModel(m => ({ ...m, thumbnail: tm.thumbnail })); 
                setFormErrors(fe => err.length ? [ ...fe.filter(fff => fff.key !== 'thumbnail'), { key: 'thumbnail', message: err[0] }] : [ ...fe.filter(fff => fff.key !== 'thumbnail')]);
                setTouched(true);
              }} 
              labelPlacement="none"
            />
          </div>
        </div>
        <div className="m-4 text-gray-400">

          <div className="my-2">
            { !(model.period === 'Once' || model.period === 'Period') &&
              <div className='text-lg font-semibold text-slate-500 ml-2'>
                { periodPhrase }
                <span className='text-md text-gray-600'>,&nbsp;starting&nbsp;</span>
              </div>
            }
            <div className="text-md font-semibold">

              <div className="inline-block">
                <QuickForm<Pick<FormEvent, "month">>
                  schema={monthPartitionedSchema}
                  init={{month: model.month}}
                  onInput={(err, mm) => {
                    setModel(m => ({ ...m, month: mm.month })); 
                    setFormErrors(fe => err.length ? [ ...fe.filter(fff => fff.key !== 'month'), { key: 'month', message: err[0] }] : [ ...fe.filter(fff => fff.key !== 'month')]);
                    setTouched(true);
                  }}
                  labelPlacement="none"
                />
              </div>
              <div className="inline-block">
                <QuickForm<Pick<FormEvent, "day">>
                  schema={dayPartitionedSchema}
                  init={{day: model.day}}
                  onInput={(err, dm) => {
                    setModel(m => ({ ...m, day: parseInt(dm.day as string) })); 
                    setFormErrors(fe => err.length ? [ ...fe.filter(fff => fff.key !== 'day'), { key: 'day', message: err[0] }] : [ ...fe.filter(fff => fff.key !== 'day')]);
                    setTouched(true);
                  }}
                  labelPlacement="none"
                />
              </div>
              <div className="inline-block">
                <QuickForm<Pick<FormEvent,"year">>
                  schema={yearPartitionedSchema}
                  init={{year: model.year}}
                  onInput={(err, ym) => {
                    setModel(m => ({ ...m, year: parseInt(ym.year as string) })); 
                    setFormErrors(fe => err.length ? [ ...fe.filter(fff => fff.key !== 'year'), { key: 'year', message: err[0] }] : [ ...fe.filter(fff => fff.key !== 'year')]);
                    setTouched(true);
                  }}
                  labelPlacement="none"
                />
              </div>
              <span className='text-md text-gray-600 align-top m-1'>at</span>
              <div className="inline-block">
                <QuickForm<Pick<FormEvent,"time">>
                  schema={timePartitionedSchema}
                  init={{time: model.time}}
                  onInput={(err, tm) => {
                    setModel(m => ({ ...m, time: tm.time })); 
                    setFormErrors(fe => err.length ? [ ...fe.filter(fff => fff.key !== 'time'), { key: 'time', message: err[0] }] : [ ...fe.filter(fff => fff.key !== 'time')]);
                    setTouched(true);
                  }}
                  labelPlacement="none"
                />
              </div>
            </div>
            <div className="text-gray-500">
              <QuickForm<Pick<FormEvent, "period" | "location" | "website" | "addressa" | "addressb" | "description">>
                schema={remainingPartitionSchema}
                init={{
                  period: model.period,
                  location: model.location,
                  website: model.website,
                  addressa: model.addressa,
                  addressb: model.addressb,
                  description: model.description
                }}
                onInput={(err, rm) => {
                  setModel(m => ({ ...m, ...rm })); 
                  setFormErrors(fe => {
                    [ "period", "location", "website", "addressa", "addressb", "description" ].forEach(k => {
                      fe = fe.filter(fff => fff.key !== k)
                    });
                    err.forEach(e => {
                      const key = e.split(' ')[0];
                      fe = [ ...fe.filter(fff => fff.key !== key), { key: key, message: e }]
                    })
                    return fe;
                  });
                  setTouched(true);
                }}
                labelPlacement="none"
              />
            </div>
          </div>

        </div>

        <div className="flex mt-3 my-2 pr-4">
          {/* {
            (touched && !!formErrors.length) &&
              <select 
                className="inline-block alert alert-error mr-2 h-12 pt-4 text-sm">
                { 
                  formErrors.map(err => (<option className="text-xs">{err.message}</option>))
                }
              </select>
          } */}
          <button className={`btn btn-primary mr-2 ml-auto`} disabled={!touched || !!Object.keys(formErrors).length} onClick={() => { resolve(model as EventPerformance); }}>Submit</button>
          <button className="btn btn-warning" onClick={() => { resolve(null); }}>Cancel</button>
        </div>


      </div>

    </div>
  );
}

export default VerticalEventForm;